<?php
require_once __DIR__.'/includes/bootstrap.php';
require_once __DIR__.'/includes/catalog.php';
require_once __DIR__.'/includes/cart.php';
$pageTitle = 'Giỏ hàng của bạn | CellphoneS';
$activePage = 'cart';
$databaseError = false;
try { $items = cart_items(); } catch (PDOException $exception) { error_log($exception->getMessage()); $items = []; $databaseError = true; http_response_code(503); }
$total = array_sum(array_column($items, 'line_total'));
$quantity = array_sum(array_column($items, 'quantity'));
require __DIR__.'/includes/header.php';
?>
<main class="container cart-page"><a href="<?= e(url('index.php')) ?>" class="back-link"><?= icon('back') ?> Tiếp tục khám phá</a><div class="cart-heading"><div><span class="eyebrow">GÓC MUA SẮM CỦA BẠN</span><h1>Giỏ hàng <span><?= $quantity ?> sản phẩm</span></h1></div><?= icon('bag') ?></div>
<?php if ($databaseError): ?><div class="empty-state"><?= icon('box') ?><h2>Chưa thể tải giỏ hàng</h2><p>Vui lòng kiểm tra kết nối MySQL và thử lại.</p><a class="button-primary" href="<?= e(url('cart.php')) ?>">Thử lại</a></div>
<?php elseif (!$items): ?><div class="empty-cart"><div class="empty-cart-art"><?= icon('bag') ?><span><?= icon('plus') ?></span></div><h2>Giỏ hàng đang chờ lựa chọn của bạn</h2><p>Một thiết bị mới, một góc máy đầy cảm hứng.<br>Cùng tìm sản phẩm phù hợp với bạn nhé!</p><a class="button-primary" href="<?= e(url('index.php')) ?>">Khám phá sản phẩm <?= icon('arrow') ?></a></div>
<?php else: ?><div class="cart-layout"><section class="cart-items" aria-label="Sản phẩm trong giỏ"><div class="cart-list-heading"><span>Sản phẩm</span><span>Số lượng & thành tiền</span></div><?php foreach ($items as $item): ?><article class="cart-item" data-cart-row="<?= (int)$item['id'] ?>"><a class="cart-product-image" href="<?= e(url('product.php?slug='.rawurlencode($item['slug']))) ?>"><img src="<?= e(product_image_url($item)) ?>" alt="<?= e($item['name']) ?>" width="150" height="135"></a><div class="cart-item-info"><span class="cart-item-brand"><?= e($item['brand']) ?></span><a href="<?= e(url('product.php?slug='.rawurlencode($item['slug']))) ?>"><h2><?= e($item['name']) ?></h2></a><p><?= e(implode(' · ', product_chips($item))) ?></p><div class="cart-unit-price"><strong><?= money($item['price']) ?></strong><?php if ($item['old_price'] > $item['price']): ?><del><?= money($item['old_price']) ?></del><?php endif; ?></div><button type="button" class="remove-item" data-remove-cart="<?= (int)$item['id'] ?>"><?= icon('trash') ?> Xóa sản phẩm</button></div><div class="cart-item-controls"><div class="quantity-control"><button type="button" data-update-cart="<?= (int)$item['id'] ?>" data-quantity="<?= (int)$item['quantity'] - 1 ?>" aria-label="Giảm số lượng <?= e($item['name']) ?>" <?= (int)$item['quantity'] <= 1 ? 'disabled' : '' ?>><?= icon('minus') ?></button><span aria-label="Số lượng"><?= (int)$item['quantity'] ?></span><button type="button" data-update-cart="<?= (int)$item['id'] ?>" data-quantity="<?= (int)$item['quantity'] + 1 ?>" aria-label="Tăng số lượng <?= e($item['name']) ?>" <?= (int)$item['quantity'] >= min(99,(int)$item['stock']) ? 'disabled' : '' ?>><?= icon('plus') ?></button></div><strong><?= money($item['line_total']) ?></strong></div></article><?php endforeach; ?><div class="cart-saved-note"><?= icon('shield') ?> Giỏ hàng được lưu trong phiên truy cập của bạn.</div></section>
<aside class="cart-summary"><h2>Thông tin giỏ hàng</h2><div class="summary-line"><span>Tạm tính (<?= $quantity ?> sản phẩm)</span><strong><?= money($total) ?></strong></div><div class="summary-line"><span>Vận chuyển</span><span>Chưa áp dụng</span></div><div class="summary-total"><span>Tổng cộng</span><strong><?= money($total) ?></strong></div><div class="cart-no-checkout"><?= icon('check') ?><p><strong>Đã lưu lựa chọn của bạn</strong>Bạn có thể tiếp tục thêm hoặc điều chỉnh sản phẩm trong giỏ.</p></div><a href="<?= e(url('index.php')) ?>" class="button-primary">Tiếp tục mua sắm <?= icon('arrow') ?></a><p class="summary-footnote">Website demo chỉ hỗ trợ giỏ hàng.<br>Không thu tiền hoặc tạo đơn thanh toán.</p></aside></div><?php endif; ?>
</main>
